+/**
+ * In-memory workflow for purchase-request approvals.
+ *
+ * Records kept by the service are never returned directly: callers always get
+ * a snapshot, so changing a result cannot alter the workflow state.
+ */
+export class ApprovalService {
+  constructor(clock = () => new Date().toISOString()) {
+    this.clock = clock;
+    this.requests = new Map();
+    this.audit = [];
+    this.idempotency = new Map();
+  }
+
+  submit({ id, requesterId, amount, reason }) {
+    if (!Number.isFinite(amount) || amount <= 0) {
+      throw new Error('amount must be a finite positive number');
+    }
+    if (this.requests.has(id)) {
+      throw new Error('duplicate request id');
+    }
+
+    const request = { id, requesterId, amount, reason, status: 'pending' };
+    this.requests.set(id, request);
+    return snapshot(request);
+  }
+
+  decide(id, { actorId, role, action, idempotencyKey }) {
+    const request = this.requests.get(id);
+    if (!request) throw new Error('not found');
+
+    // A retry is recognised before checking the current state, since after a
+    // successful first call the request is no longer pending.
+    const key = idempotencyKey === undefined || idempotencyKey === null
+      ? undefined
+      : `${typeof idempotencyKey}:${String(idempotencyKey)}`;
+    const decisions = this.idempotency.get(id);
+    if (key !== undefined && decisions?.has(key)) {
+      return snapshot(request);
+    }
+
+    if (role !== 'manager' && role !== 'admin') {
+      throw new Error('only a manager or admin can decide');
+    }
+    if (actorId === request.requesterId) {
+      throw new Error('requester cannot decide their own request');
+    }
+    if (action !== 'approve' && action !== 'reject') {
+      throw new Error('invalid decision action');
+    }
+    if (request.status !== 'pending') {
+      throw new Error('request is no longer pending');
+    }
+
+    request.status = action === 'approve' ? 'approved' : 'rejected';
+    this.audit.push({ requestId: id, actorId, action, at: this.clock() });
+    if (key !== undefined) {
+      const keys = decisions ?? new Set();
+      keys.add(key);
+      this.idempotency.set(id, keys);
+    }
+    return snapshot(request);
+  }
+
+  get(id) {
+    const request = this.requests.get(id);
+    return request === undefined ? undefined : snapshot(request);
+  }
+
+  history(id) {
+    return this.audit
+      .filter((event) => event.requestId === id)
+      .map((event) => snapshot(event));
+  }
+}
+
+function snapshot(value) {
+  return structuredClone(value);
+}
*** End Patch";
const r = await tools.apply_patch(patch);
text(typeof r === "string" ? r : JSON.stringify(r));

